-- Migration 031: real, individually researched orgs for Washington, DC
-- and Baltimore, MD (30 orgs) -- second batch, continuing to fill the
-- previously-empty music/faith categories.

insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
values
  ('f3000000-0000-4000-8000-000000000001', null, 'DC Youth Orchestra Program', 'DC Youth Orchestra Program gives young musicians across the district pre-professional orchestral training and real performance experience. Volunteers help with concerts and special events like DCYOPalooza, and pitch in on Saturday program days with music distribution and chair set-up.', 'https://www.dcyop.org/', 'https://www.google.com/s2/favicons?domain=www.dcyop.org&sz=128', 'music', array['music or performance','family friendly','recurring','one-time'], false, false, 14, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000002', null, 'American Youth Philharmonic Orchestras', 'American Youth Philharmonic Orchestras trains more than 600 musicians ages 7-21 across the DC area, and its talented high schoolers give weekly, private music lessons to underserved elementary and middle schoolers through the Music Buddies program. A great pick if you play an instrument and want real teaching experience.', 'https://www.aypo.org/', 'https://www.google.com/s2/favicons?domain=www.aypo.org&sz=128', 'music', array['music or performance','teaching or tutoring','skilled volunteers wanted','weekly'], false, false, 14, 'United States', 'VA', 'Arlington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000003', null, 'Catholic Charities DC', 'Catholic Charities DC runs more than 65 programs across the District and nearby Maryland counties, serving over 116,000 people of every background each year. Volunteers can pick a one-time shift or a weekly commitment -- serving food in shelters, mentoring, or helping with administrative support -- and you don''t have to be Catholic to join.', 'https://www.catholiccharitiesdc.org/', 'https://www.google.com/s2/favicons?domain=www.catholiccharitiesdc.org&sz=128', 'faith', array['faith-based','no experience needed','recurring','one-time'], false, false, 14, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000004', null, 'Jewish Federation of Greater Washington', 'The Jewish Federation of Greater Washington connects volunteers with hands-on service rooted in Jewish values across the DMV, from food distribution to community events. Its Jconnect hub lists volunteer opportunities open to anyone who wants to get involved, regardless of background.', 'https://www.shalomdc.org/', 'https://www.google.com/s2/favicons?domain=www.shalomdc.org&sz=128', 'faith', array['faith-based','no experience needed','family friendly','recurring'], false, false, 14, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000005', null, 'Rock Creek Conservancy', 'Rock Creek Conservancy protects and restores Rock Creek Park, and its summer Conservation Corps gives high schoolers hands-on field experience in invasive plant removal, litter cleanups, and water quality monitoring. Regular volunteer days are open to anyone who wants to plant trees or pull weeds for a few hours outdoors.', 'https://www.rockcreekconservancy.org/', 'https://www.google.com/s2/favicons?domain=www.rockcreekconservancy.org&sz=128', 'environment', array['outdoors','good for crews','no experience needed','physical work'], false, false, 14, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000006', null, 'Anacostia Watershed Society', 'Anacostia Watershed Society leads the fight to restore the Anacostia River, including the massive annual Earth Day cleanup that pulls thousands of volunteers out along the riverbanks. Shifts are simple and no-experience-needed -- grab a trash bag and gloves and help stop pollution before it reaches the water.', 'https://www.anacostiaws.org/', 'https://www.google.com/s2/favicons?domain=www.anacostiaws.org&sz=128', 'environment', array['outdoors','good for crews','no experience needed','one-time'], false, false, 12, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000007', null, 'Humane Rescue Alliance', 'Humane Rescue Alliance runs DC''s animal shelter and rescue operations, caring for and training animals, running adoption events, and distributing pet food to families in need. Younger teens can pitch in through youth projects and supply drives while the full in-shelter Junior Volunteer program is on hold.', 'https://www.humanerescuealliance.org/', 'https://www.google.com/s2/favicons?domain=www.humanerescuealliance.org&sz=128', 'animals', array['animal handling','family friendly','one-time','recurring'], false, false, 13, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000008', null, 'Black Girls Code DC', 'Black Girls Code DC has introduced more than 600 girls a year to coding and STEM since 2015, running workshops in AI, robotics, web design, and 3D printing. Volunteers with any tech comfort level can mentor a session or help run event logistics for the next generation of coders.', 'https://www.blackgirlscode.com/', 'https://www.google.com/s2/favicons?domain=www.blackgirlscode.com&sz=128', 'tech', array['tech skills useful','teaching or tutoring','training provided','one-time'], false, false, 16, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000009', null, 'Children''s National Hospital', 'Children''s National Hospital runs a Summer High School Volunteer Program where students 15+ commit to a six-week session greeting families and supporting hospital staff, plus a year-round program for a longer commitment. It''s a strong pick for anyone considering a future in medicine who wants real hospital exposure.', 'https://www.childrensnational.org/', 'https://www.google.com/s2/favicons?domain=www.childrensnational.org&sz=128', 'medicine', array['training provided','skilled volunteers wanted','indoors','recurring'], false, false, 15, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000010', null, 'DC Central Kitchen', 'DC Central Kitchen turns donated and surplus food into meals for people facing hunger across the District, running community meal programs alongside culinary job training. Volunteers help prep and pack meals in the kitchen -- a good pick for a crew that likes hands-on, physical work.', 'https://dccentralkitchen.org/', 'https://www.google.com/s2/favicons?domain=dccentralkitchen.org&sz=128', 'food', array['good for crews','no experience needed','physical work','recurring'], false, false, 14, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000011', null, 'Food & Friends', 'Food & Friends prepares and delivers medically tailored meals to DC-area neighbors living with serious illness, including many homebound seniors. Volunteers help pack meals in the kitchen or drive delivery routes with a parent, checking in with clients along the way.', 'https://foodandfriends.org/', 'https://www.google.com/s2/favicons?domain=foodandfriends.org&sz=128', 'seniors', array['chill first-timer pick','family friendly','recurring','weekly'], false, false, 16, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000012', null, 'Special Olympics DC', 'Special Olympics DC welcomes volunteers of every age and commitment level, from a single afternoon to season-long coaching. Roles range from checking in athletes and handing out t-shirts to jumping into a sport clinic -- no experience needed, just enthusiasm.', 'https://specialolympicsdc.org/', 'https://www.google.com/s2/favicons?domain=specialolympicsdc.org&sz=128', 'sports', array['sports or coaching','no experience needed','family friendly','one-time'], false, false, 14, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000013', null, 'VA Washington DC Medical Center Voluntary Service', 'The VA Washington DC Medical Center relies on volunteers to support veterans receiving care, from greeting patients to assisting staff across the hospital. It''s a meaningful way to give back to those who served, with roles suited to a range of ages and interests.', 'https://www.va.gov/washington-dc-health-care/work-with-us/volunteer-or-donate/', 'https://www.google.com/s2/favicons?domain=www.va.gov&sz=128', 'veterans', array['training provided','indoors','recurring','skilled volunteers wanted'], false, false, 16, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000014', null, 'DC Public Library', 'DC Public Library runs volunteer programs across its branches, including reading buddies and homework help for younger kids. It''s a chill, low-pressure pick for anyone who loves books and wants a first taste of volunteering.', 'https://www.dclibrary.org/', 'https://www.google.com/s2/favicons?domain=www.dclibrary.org&sz=128', 'education', array['chill first-timer pick','teaching or tutoring','weekly','indoors'], false, false, 14, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000015', null, 'Martha''s Table', 'Martha''s Table has supported DC families for decades with free groceries, meals, and early childhood education across the city. Volunteers pack grocery bags, help run family programming, or support the on-site markets that bring fresh food into underserved neighborhoods.', 'https://marthastable.org/', 'https://www.google.com/s2/favicons?domain=marthastable.org&sz=128', 'community', array['good for crews','family friendly','no experience needed','recurring'], false, false, 13, 'United States', 'DC', 'Washington', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000016', null, 'Living Classrooms Foundation -- Ascend Through Music', 'Ascend Through Music has served Baltimore and DC youth since 2016, pairing musically inclined volunteers one-on-one with students to explore instruments, mentorship, and performance. No formal teaching background needed -- just some music experience and patience.', 'https://livingclassrooms.org/programs/ascend-through-music', 'https://www.google.com/s2/favicons?domain=livingclassrooms.org&sz=128', 'music', array['music or performance','teaching or tutoring','training provided','weekly'], false, false, 15, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000017', null, 'Hit Me With Music Foundation', 'Hit Me With Music Foundation runs afterschool music programs for Baltimore students in grades K-8, expanding access to quality music education citywide. Volunteers help lead sessions, assist with instruments, or support event logistics.', 'https://www.hmwmfoundation.org/', 'https://www.google.com/s2/favicons?domain=www.hmwmfoundation.org&sz=128', 'music', array['music or performance','teaching or tutoring','family friendly','recurring'], false, false, 15, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000018', null, 'BSO OrchKids', 'BSO OrchKids, the Baltimore Symphony Orchestra''s youth program, gives Baltimore City students free instruments and daily music instruction after school and in the summer. Volunteers support program days, help with instrument care, and assist teaching artists during sessions.', 'https://orchkids.org/', 'https://www.google.com/s2/favicons?domain=orchkids.org&sz=128', 'music', array['music or performance','training provided','family friendly','seasonal'], false, false, 15, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000019', null, 'Our Lady of Victory Food Pantry', 'Our Lady of Victory''s food pantry is entirely volunteer-run, handing out groceries to Baltimore neighbors every Saturday morning. It''s a simple, welcoming shift open to volunteers of any faith or none at all.', 'https://olvictory.org/olv-food-pantry', 'https://www.google.com/s2/favicons?domain=olvictory.org&sz=128', 'faith', array['faith-based','no experience needed','chill first-timer pick','weekly'], false, false, 13, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000020', null, 'Moveable Feast', 'Moveable Feast prepares and delivers over 9,000 medically tailored meals a week to Baltimore-area neighbors living with serious illness. Volunteers help pack meal bags in the kitchen or ride along on delivery routes, a great fit for anyone who wants a hands-on, feel-good shift.', 'https://www.mfeast.org/', 'https://www.google.com/s2/favicons?domain=www.mfeast.org&sz=128', 'food', array['good for crews','no experience needed','recurring','physical work'], false, false, 14, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000021', null, 'BARCS -- Baltimore Animal Rescue and Care Shelter', 'BARCS is Baltimore''s open-admission animal shelter, caring for every animal that comes through its doors. Teens 13-15 can volunteer alongside a parent in limited shelter activities, and older teens can socialize cats, walk dogs, and help at adoption events.', 'https://www.barcs.org/', 'https://www.google.com/s2/favicons?domain=www.barcs.org&sz=128', 'animals', array['animal handling','family friendly','training provided','recurring'], false, false, 13, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000022', null, 'Blue Water Baltimore', 'Blue Water Baltimore works to restore the city''s rivers, streams, and harbor through tree plantings, trash cleanups, and stormwater projects. Volunteer days are a great way to explore Baltimore''s parks and waterways while doing real environmental work with a crew.', 'https://bluewaterbaltimore.org/', 'https://www.google.com/s2/favicons?domain=bluewaterbaltimore.org&sz=128', 'environment', array['outdoors','good for crews','no experience needed','one-time'], false, false, 13, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000023', null, 'Filbert Street Garden', 'Filbert Street Garden is a community green space in South Baltimore where volunteers help with planting, beekeeping, animal care, and seasonal beautification projects. It''s a relaxed, hands-on spot to spend an afternoon outdoors, no gardening experience required.', 'https://filbertstreetgarden.org/', 'https://www.google.com/s2/favicons?domain=filbertstreetgarden.org&sz=128', 'gardening', array['gardening skills','outdoors','no experience needed','chill first-timer pick'], false, false, 12, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000024', null, 'Civic Works Real Food Farm', 'Civic Works'' Real Food Farm grows fresh produce for Baltimore neighborhoods with limited grocery access, running an urban farm that relies on volunteer labor for planting, weeding, and harvesting. A solid pick if you want to learn real farming skills while helping close the food gap.', 'https://civicworks.com/programs/real-food-farm/', 'https://www.google.com/s2/favicons?domain=civicworks.com&sz=128', 'gardening', array['gardening skills','outdoors','physical work','recurring'], false, false, 14, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000025', null, 'Special Olympics Maryland', 'Special Olympics Maryland runs season-long sports programs across the state, recruiting coaches and sports volunteers for soccer, basketball, bowling, and more. High schoolers can volunteer for community service hours in roles from admin support to hands-on coaching.', 'https://www.somd.org/', 'https://www.google.com/s2/favicons?domain=www.somd.org&sz=128', 'sports', array['sports or coaching','training provided','recurring','family friendly'], false, false, 14, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000026', null, 'Johns Hopkins Hospital HS2 Program', 'Johns Hopkins Hospital''s HS2 summer program gives students 16-18 a seven-week, 100-hour volunteer placement helping patients find their way and supporting hospital departments. It''s one of the most recognized hospital volunteer programs in Baltimore for students eyeing healthcare careers.', 'https://www.hopkinsmedicine.org/volunteer-services', 'https://www.google.com/s2/favicons?domain=www.hopkinsmedicine.org&sz=128', 'medicine', array['training provided','skilled volunteers wanted','indoors','seasonal'], false, false, 16, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000027', null, 'The Mission Continues -- Baltimore Platoon', 'The Mission Continues'' Baltimore Platoon brings together veteran and civilian volunteers to tackle neighborhood revitalization, food access, and community health projects citywide. Service projects are open to anyone who wants to work alongside veterans making a hands-on difference.', 'https://www.missioncontinues.org/service-platoon/Baltimore/', 'https://www.google.com/s2/favicons?domain=www.missioncontinues.org&sz=128', 'veterans', array['good for crews','physical work','one-time','leadership role'], false, false, 16, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000028', null, 'Maryland Center for Veterans Education & Training (MCVET)', 'MCVET has served more than 12,000 veterans since 1993, offering housing, job training, and support programs across Baltimore. Volunteers help with community events, cookouts, and special programs that support veterans rebuilding their lives.', 'https://www.mcvet.org/', 'https://www.google.com/s2/favicons?domain=www.mcvet.org&sz=128', 'veterans', array['no experience needed','family friendly','one-time','recurring'], false, false, 16, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000029', null, 'American Red Cross Central Maryland', 'The Central Maryland Red Cross trains Disaster Action Team volunteers who provide comfort and emergency resources to families displaced by house fires and other local disasters, day or night. Training is provided for every role, and some support positions can be done remotely.', 'https://www.redcross.org/local/dc-va-md-de/about-us/locations/central-maryland.html', 'https://www.google.com/s2/favicons?domain=www.redcross.org&sz=128', 'disaster', array['training provided','no experience needed','tech skills useful','recurring'], true, false, 16, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false),
  ('f3000000-0000-4000-8000-000000000030', null, 'Creative Alliance', 'Creative Alliance is a Baltimore arts hub running gallery shows, performances, and community art classes out of a renovated movie theater. Volunteers help run events, greet visitors, and support exhibitions -- a good pick for anyone into art who wants to see how a working arts nonprofit operates.', 'https://creativealliance.org/', 'https://www.google.com/s2/favicons?domain=creativealliance.org&sz=128', 'art', array['arts and crafts','one-time','good for crews','chill first-timer pick'], false, false, 14, 'United States', 'MD', 'Baltimore', true, true, 'ongoing', false)
on conflict (id) do nothing;

