  ('f4000000-0000-4000-8000-000000000013', 'f3000000-0000-4000-8000-000000000013', 'Volunteer at the VA Washington DC Medical Center', 'veterans', 'The VA Washington DC Medical Center relies on volunteers to support veterans receiving care, from greeting patients to assisting staff across the hospital. It''s a meaningful way to give back to those who served, with roles suited to a range of ages and interests.', array['training provided','indoors','recurring','skilled volunteers wanted'], 16, false, false, true, '2-3 hrs', 'https://www.va.gov/washington-dc-health-care/work-with-us/volunteer-or-donate/', 'https://www.va.gov/washington-dc-health-care/work-with-us/volunteer-or-donate/', '2026-01-01T00:00:00Z', 'Washington', 'DC'),
  ('f4000000-0000-4000-8000-000000000014', 'f3000000-0000-4000-8000-000000000014', 'Volunteer at DC Public Library', 'education', 'DC Public Library runs volunteer programs across its branches, including reading buddies and homework help for younger kids. It''s a chill, low-pressure pick for anyone who loves books and wants a first taste of volunteering.', array['chill first-timer pick','teaching or tutoring','weekly','indoors'], 14, false, false, true, '1-2 hrs', 'https://www.dclibrary.org/get-involved/volunteer-library', 'https://www.dclibrary.org/get-involved/volunteer-library', '2026-01-01T00:00:00Z', 'Washington', 'DC'),
  ('f4000000-0000-4000-8000-000000000015', 'f3000000-0000-4000-8000-000000000015', 'Volunteer with Martha''s Table', 'community', 'Martha''s Table has supported DC families for decades with free groceries, meals, and early childhood education across the city. Volunteers pack grocery bags, help run family programming, or support the on-site markets that bring fresh food into underserved neighborhoods.', array['good for crews','family friendly','no experience needed','recurring'], 13, false, false, true, '2-3 hrs', 'https://marthastable.org/', 'https://marthastable.org/', '2026-01-01T00:00:00Z', 'Washington', 'DC'),
  ('f4000000-0000-4000-8000-000000000016', 'f3000000-0000-4000-8000-000000000016', 'Volunteer with Ascend Through Music', 'music', 'Ascend Through Music has served Baltimore and DC youth since 2016, pairing musically inclined volunteers one-on-one with students to explore instruments, mentorship, and performance. No formal teaching background needed -- just some music experience and patience.', array['music or performance','teaching or tutoring','training provided','weekly'], 15, false, false, true, '1-2 hrs', 'https://livingclassrooms.org/volunteer', 'https://livingclassrooms.org/volunteer', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000017', 'f3000000-0000-4000-8000-000000000017', 'Volunteer with Hit Me With Music Foundation', 'music', 'Hit Me With Music Foundation runs afterschool music programs for Baltimore students in grades K-8, expanding access to quality music education citywide. Volunteers help lead sessions, assist with instruments, or support event logistics.', array['music or performance','teaching or tutoring','family friendly','recurring'], 15, false, false, true, '2 hrs', 'https://www.hmwmfoundation.org/', 'https://www.hmwmfoundation.org/', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000018', 'f3000000-0000-4000-8000-000000000018', 'Volunteer with BSO OrchKids', 'music', 'BSO OrchKids, the Baltimore Symphony Orchestra''s youth program, gives Baltimore City students free instruments and daily music instruction after school and in the summer. Volunteers support program days, help with instrument care, and assist teaching artists during sessions.', array['music or performance','training provided','family friendly','seasonal'], 15, false, false, true, '2-3 hrs', 'https://orchkids.org/get-involved/volunteer-opportunities/', 'https://orchkids.org/get-involved/volunteer-opportunities/', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000019', 'f3000000-0000-4000-8000-000000000019', 'Saturday Shift at OLV Food Pantry', 'faith', 'Our Lady of Victory''s food pantry is entirely volunteer-run, handing out groceries to Baltimore neighbors every Saturday morning. It''s a simple, welcoming shift open to volunteers of any faith or none at all.', array['faith-based','no experience needed','chill first-timer pick','weekly'], 13, false, false, true, '2 hrs', 'https://olvictory.org/olv-food-pantry', 'https://olvictory.org/olv-food-pantry', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000020', 'f3000000-0000-4000-8000-000000000020', 'Volunteer with Moveable Feast', 'food', 'Moveable Feast prepares and delivers over 9,000 medically tailored meals a week to Baltimore-area neighbors living with serious illness. Volunteers help pack meal bags in the kitchen or ride along on delivery routes, a great fit for anyone who wants a hands-on, feel-good shift.', array['good for crews','no experience needed','recurring','physical work'], 14, false, false, true, '2-3 hrs', 'https://www.mfeast.org/become-a-volunteer/', 'https://www.mfeast.org/become-a-volunteer/', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000021', 'f3000000-0000-4000-8000-000000000021', 'Volunteer with BARCS', 'animals', 'BARCS is Baltimore''s open-admission animal shelter, caring for every animal that comes through its doors. Teens 13-15 can volunteer alongside a parent in limited shelter activities, and older teens can socialize cats, walk dogs, and help at adoption events.', array['animal handling','family friendly','training provided','recurring'], 13, false, false, true, '2-3 hrs', 'https://www.barcs.org/volunteer', 'https://www.barcs.org/volunteer', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000022', 'f3000000-0000-4000-8000-000000000022', 'Volunteer with Blue Water Baltimore', 'environment', 'Blue Water Baltimore works to restore the city''s rivers, streams, and harbor through tree plantings, trash cleanups, and stormwater projects. Volunteer days are a great way to explore Baltimore''s parks and waterways while doing real environmental work with a crew.', array['outdoors','good for crews','no experience needed','one-time'], 13, false, false, true, '2-3 hrs', 'https://bluewaterbaltimore.org/', 'https://bluewaterbaltimore.org/', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000023', 'f3000000-0000-4000-8000-000000000023', 'Volunteer at Filbert Street Garden', 'gardening', 'Filbert Street Garden is a community green space in South Baltimore where volunteers help with planting, beekeeping, animal care, and seasonal beautification projects. It''s a relaxed, hands-on spot to spend an afternoon outdoors, no gardening experience required.', array['gardening skills','outdoors','no experience needed','chill first-timer pick'], 12, false, false, true, '2 hrs', 'https://filbertstreetgarden.org/', 'https://filbertstreetgarden.org/', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000024', 'f3000000-0000-4000-8000-000000000024', 'Volunteer at Real Food Farm', 'gardening', 'Civic Works'' Real Food Farm grows fresh produce for Baltimore neighborhoods with limited grocery access, running an urban farm that relies on volunteer labor for planting, weeding, and harvesting. A solid pick if you want to learn real farming skills while helping close the food gap.', array['gardening skills','outdoors','physical work','recurring'], 14, false, false, true, '2-3 hrs', 'https://civicworks.com/programs/real-food-farm/', 'https://civicworks.com/programs/real-food-farm/', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000025', 'f3000000-0000-4000-8000-000000000025', 'Volunteer with Special Olympics Maryland', 'sports', 'Special Olympics Maryland runs season-long sports programs across the state, recruiting coaches and sports volunteers for soccer, basketball, bowling, and more. High schoolers can volunteer for community service hours in roles from admin support to hands-on coaching.', array['sports or coaching','training provided','recurring','family friendly'], 14, false, false, true, 'Full day', 'https://www.somd.org/volunteer/volunteer-opportunities/', 'https://www.somd.org/volunteer/volunteer-opportunities/', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000026', 'f3000000-0000-4000-8000-000000000026', 'HS2 Summer Program at Johns Hopkins Hospital', 'medicine', 'Johns Hopkins Hospital''s HS2 summer program gives students 16-18 a seven-week, 100-hour volunteer placement helping patients find their way and supporting hospital departments. It''s one of the most recognized hospital volunteer programs in Baltimore for students eyeing healthcare careers.', array['training provided','skilled volunteers wanted','indoors','seasonal'], 16, false, false, true, '5-6 hrs', 'https://www.hopkinsmedicine.org/volunteer-services', 'https://www.hopkinsmedicine.org/volunteer-services', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000027', 'f3000000-0000-4000-8000-000000000027', 'Volunteer with The Mission Continues Baltimore', 'veterans', 'The Mission Continues'' Baltimore Platoon brings together veteran and civilian volunteers to tackle neighborhood revitalization, food access, and community health projects citywide. Service projects are open to anyone who wants to work alongside veterans making a hands-on difference.', array['good for crews','physical work','one-time','leadership role'], 16, false, false, true, 'Full day', 'https://www.missioncontinues.org/service-platoon/Baltimore/', 'https://www.missioncontinues.org/service-platoon/Baltimore/', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000028', 'f3000000-0000-4000-8000-000000000028', 'Volunteer with MCVET', 'veterans', 'MCVET has served more than 12,000 veterans since 1993, offering housing, job training, and support programs across Baltimore. Volunteers help with community events, cookouts, and special programs that support veterans rebuilding their lives.', array['no experience needed','family friendly','one-time','recurring'], 16, false, false, true, '2-3 hrs', 'https://www.mcvet.org/', 'https://www.mcvet.org/', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000029', 'f3000000-0000-4000-8000-000000000029', 'Join a Red Cross Disaster Action Team', 'disaster', 'The Central Maryland Red Cross trains Disaster Action Team volunteers who provide comfort and emergency resources to families displaced by house fires and other local disasters, day or night. Training is provided for every role, and some support positions can be done remotely.', array['training provided','no experience needed','tech skills useful','recurring'], 16, true, false, true, 'Flexible', 'https://www.redcross.org/local/dc-va-md-de/volunteer.html', 'https://www.redcross.org/local/dc-va-md-de/volunteer.html', '2026-01-01T00:00:00Z', 'Baltimore', 'MD'),
  ('f4000000-0000-4000-8000-000000000030', 'f3000000-0000-4000-8000-000000000030', 'Volunteer with Creative Alliance', 'art', 'Creative Alliance is a Baltimore arts hub running gallery shows, performances, and community art classes out of a renovated movie theater. Volunteers help run events, greet visitors, and support exhibitions -- a good pick for anyone into art who wants to see how a working arts nonprofit operates.', array['arts and crafts','one-time','good for crews','chill first-timer pick'], 14, false, false, true, '2-3 hrs', 'https://creativealliance.org/get-involved/volunteer/', 'https://creativealliance.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Baltimore', 'MD')
on conflict (id) do nothing;
